// Turn `cargo build --timings` into the two numbers that actually decide what to do about a slow
// Rust build: which crates cost the most, and how much of the machine the build managed to use.
//
// Usage: node scripts/parse-cargo-timings.mjs <cargo-timing.html>
//
// Writes validated TSV to stdout; writes nothing and exits 0 if the report is missing or its shape
// is not recognized. Cargo's HTML layout is not a stable interface, and a profiler must never be
// the reason a build fails.
//
// Safety: this file is generated by OUR cargo invocation in scripts/eas-build-pre-install.sh --
// not by EAS -- so no signing material is in scope. It is still parsed as data and every field is
// re-validated before it is printed, because the output lands in a public job summary.

import { readFileSync } from 'node:fs';

const path = process.argv[2];
if (!path) process.exit(0);

let html;
try {
  html = readFileSync(path, 'utf8');
} catch {
  process.exit(0);
}

// The array is pretty-printed JSON between `const UNIT_DATA = [` and a line that is exactly `];`.
// Bounded by the delimiters rather than regex-matched across the whole file, so a change in cargo's
// output degrades to "no table" instead of to garbage.
function extractArray(name) {
  const start = html.indexOf(`const ${name} = [`);
  if (start === -1) return null;
  const open = html.indexOf('[', start);
  const end = html.indexOf('\n];', open);
  if (end === -1) return null;
  try {
    return JSON.parse(html.slice(open, end + 2));
  } catch {
    return null;
  }
}

const units = extractArray('UNIT_DATA');
if (!Array.isArray(units) || units.length === 0) process.exit(0);

// Crate names come from the dependency graph, but the output is public, so they are held to a
// shape: a name that does not look like a crate name is dropped rather than printed.
//
// Lowercase and 39 characters, not "alphanumeric up to 64". The looser rule was written first and
// scripts/test-build-profile-isolation.sh rejected it for the second time in this change: a base64
// credential is 56 mixed-case alphanumerics, which is a perfectly good "name" to a regex and a
// disaster in a public summary. Real crate names are lowercase and short; the longest in this
// graph is `opentelemetry-appender-tracing` at 30. A legitimate name that this drops costs one row
// of a diagnostic table.
const NAME = /^[a-z0-9][a-z0-9._+-]{0,38}$/;

const byCrate = new Map();
let unitSeconds = 0;
let wallSeconds = 0;

for (const unit of units) {
  const name = typeof unit?.name === 'string' ? unit.name : '';
  const duration = Number(unit?.duration);
  const start = Number(unit?.start);
  if (!NAME.test(name) || !Number.isFinite(duration) || duration < 0) continue;
  byCrate.set(name, (byCrate.get(name) ?? 0) + duration);
  unitSeconds += duration;
  if (Number.isFinite(start)) wallSeconds = Math.max(wallSeconds, start + duration);
}

if (byCrate.size === 0) process.exit(0);

const out = [];
// Totals first: the ratio of compile-seconds to wall-seconds is how many cores the build kept busy,
// which is the number that says whether the answer is more parallelism or less work.
out.push(`_unit_ms\t${Math.round(unitSeconds * 1000)}`);
out.push(`_wall_ms\t${Math.round(wallSeconds * 1000)}`);
out.push(`_crates\t${byCrate.size}`);

// Every crate, not just the slow ones: this output is what gets uploaded, and the renderer does
// its own truncation for the inline table. Cargo's own HTML report is deliberately NOT published
// (see scripts/build-report.sh), so this file is the whole long tail.
for (const [name, seconds] of [...byCrate].sort((a, b) => b[1] - a[1])) {
  out.push(`${name}\t${Math.round(seconds * 1000)}`);
}

process.stdout.write(out.join('\n') + '\n');
